function renderGoals(){const d=analyticsPeriods.month,done=state.tasksDone.length,ap=state.goals.appointments,cl=state.goals.closings;return header('GOALS & IMPACT','Measure what happens after insight.','Track real workflow actions separately from outcomes. The values below are fictional demo metrics.',btn('Download impact report ↓','data-download="impact"'))+
 `<div class="panel-grid equal"><section class="panel"><div class="eyebrow">MONTHLY GOALS</div><h2>Set the target. See progress.</h2><form id="goalsForm"><div class="form-grid"><label class="form-field">Appointment goal<input type="number" min="1" max="10000" name="appointments" required value="${ap}"></label><label class="form-field">Closing goal<input type="number" min="1" max="10000" name="closings" required value="${cl}"></label></div><div class="form-actions">${btn('Save demo goals','type="submit"','primary')}</div></form><div class="divider"></div><div class="row-line"><div class="row-main"><strong>Appointments: ${d.appointments} / ${ap}</strong><div class="progress"><i style="width:${Math.min(100,pct(d.appointments,ap))}%"></i></div></div><span class="pill">${pct(d.appointments,ap)}%</span></div><div class="row-line"><div class="row-main"><strong>Closings: ${d.closings} / ${cl}</strong><div class="progress"><i style="width:${Math.min(100,pct(d.closings,cl))}%"></i></div></div><span class="pill">${pct(d.closings,cl)}%</span></div></section><section class="panel soft"><div class="eyebrow">ATTRIBUTION STANDARD</div><h2>Activity is not the same as impact.</h2><p class="muted-copy">EstateIQ should distinguish recommended opportunities, completed actions, conversations logged by the customer and verified transaction outcomes.</p><div class="callout warning">No actual sale, commission, or return on investment is claimed by this prototype.</div></section></div>`+
 metrics([['Recommendations reviewed',state.propertiesViewed.length,'Unique reports opened'],['Opportunities saved',state.saved.length,'Explicit user selections'],['Priorities completed',done,'Demo workflow actions'],['Draft actions approved',state.actions.length,'Recorded locally, never sent']])+
 `<section class="panel"><div class="eyebrow">OPPORTUNITY → ACTION → OUTCOME</div><h2>Example measurement chain</h2><div class="report-line"><span>Recommendations delivered</span><strong>${properties.length}</strong></div><div class="report-line"><span>Recommendations opened</span><strong>${state.propertiesViewed.length}</strong></div><div class="report-line"><span>Actions approved in the preview</span><strong>${state.actions.length}</strong></div><div class="report-line"><span>Client conversations confirmed</span><strong>Not connected</strong></div><div class="report-line"><span>Transactions verified</span><strong>Not connected</strong></div></section>`;}
function renderTeam(){if(state.role!=='brokerage')return header('BROKERAGE INTELLIGENCE','Your business, your visibility.','This view belongs to a brokerage account. Switch to the Brokerage preview to explore role-based team tools.',btn('Preview Brokerage','data-role="brokerage"','primary'))+`<div class="callout">An individual Agent plan does not automatically expose brokerage-wide or other agents’ private CRM records.</div>`;
 const agents=[...team,...state.teamAdded];return header('BROKERAGE INTELLIGENCE','One brokerage. Individual intelligence.','Every included seat receives the Agent experience. Leadership sees permitted aggregate activity and team goals.',btn('Add demo seat +','data-add-agent','primary'))+
 metrics([['Agent seats used',agents.length,'10 included in draft plan'],['Available included seats',Math.max(0,10-agents.length),'Additional seats priced separately'],['Team appointments',18,'Illustrative month'],['Sample pipeline',money(4200000),'Aggregated example']])+
 `<div class="plan-strip"><strong>EstateIQ Brokerage · Draft $1,499/mo</strong> · 10 full Agent seats included · Founding pilot concept $899/mo. These prices are proposals, not live checkout.</div><div class="panel-grid"><section class="panel"><div class="panel-title"><div><div class="eyebrow">TEAM OVERVIEW</div><h2>Full Agent access for each seat</h2></div><span class="pill">Role-based concept</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Agent</th><th>Role</th><th>Appointments</th><th>Demo status</th></tr></thead><tbody>${agents.map(a=>`<tr><td>${escapeHtml(a.name)}</td><td>${escapeHtml(a.role)}</td><td>${a.appointments}</td><td><span class="pill">Active preview</span></td></tr>`).join('')}</tbody></table></div><p class="subtle-note">Adding a seat changes the local simulation only; no email invitation is sent.</p></section><section class="panel soft"><div class="eyebrow">WEEKLY LEADERSHIP BRIEFING</div><h2>Surface what needs a manager’s attention.</h2><div class="ticket"><span class="ticket-icon">✧</span><div class="row-main"><strong>Review follow-up coverage</strong><small>${pendingContacts().length} example contacts remain in the queue. Only aggregate counts are shown here.</small></div></div><div class="ticket"><span class="ticket-icon">⌖</span><div class="row-main"><strong>Check the appointment goal</strong><small>${pct(18,state.goals.appointments)}% of the fictional monthly appointment target.</small></div></div><div class="ticket"><span class="ticket-icon">▤</span><div class="row-main"><strong>Share a reviewed briefing</strong><small>Export the report before distributing it; permission settings remain a production requirement.</small></div></div>${btn('Open weekly report ↗','data-nav="reports"','primary')}</section></div>`;}
function renderReports(){return header('WEEKLY BRIEFINGS','Insights ready for review.','Download a transparent report that separates recommendations, recorded actions and unknown outcomes.',btn('Export briefing ↓','data-download="brief"','primary')+btn('Print view','data-print','secondary'))+
 `<div class="panel-grid"><section class="panel"><div class="eyebrow">ESTATEIQ · SAMPLE WEEKLY REPORT</div><h2>Bay Area Realty</h2><div class="report-line"><span>Property and land candidates</span><strong>${properties.length-state.dismissed.length}</strong></div><div class="report-line"><span>Buyer-to-property matches</span><strong>${properties.reduce((n,p)=>n+matchingBuyers(p).length,0)}</strong></div><div class="report-line"><span>Follow-ups awaiting review</span><strong>${pendingContacts().length}</strong></div><div class="report-line"><span>Priorities completed</span><strong>${state.tasksDone.length}/${baseTasks.length}</strong></div><div class="report-line"><span>Recommended opportunities opened</span><strong>${state.propertiesViewed.length}</strong></div><div class="report-line"><span>Local draft approvals</span><strong>${state.actions.length}</strong></div><div class="callout"><strong>Recommended focus:</strong> Investigate buyer-aligned research candidates, review overdue sample contacts, and verify land records before advising on potential use.</div><p class="subtle-note">All people, property information and performance data are fictional.</p></section><section class="panel soft"><div class="eyebrow">REPORT LIBRARY</div><h2>Export what your team can use.</h2><div class="row-line"><div class="row-main"><strong>Weekly business briefing</strong><small>Plain text summary with methodology and demo disclosure.</small></div>${btn('TXT ↓','data-download="brief"','ghost')}</div><div class="row-line"><div class="row-main"><strong>Opportunity activity</strong><small>CSV of report views, saved research and local workflow.</small></div>${btn('CSV ↓','data-download="impact"','ghost')}</div><div class="row-line"><div class="row-main"><strong>Sample CRM template</strong><small>Fictional example columns for future authorized import mapping.</small></div>${btn('CSV ↓','data-download="crm"','ghost')}</div></section></div>`;}
function renderProfile(){const p=profile();const current=String(p.name||'Austin').trim();return header('ACCOUNT & PREFERENCES','Your workspace, your way.','Update the fictional profile and workspace preferences for this browser preview.',`<a class="action-button secondary" href="account.html">Account & security ↗</a>`)+
 `<div class="profile-intro"><span class="profile-large-avatar">${escapeHtml((current[0]||'A').toUpperCase())}</span><div><strong>${escapeHtml(current)}</strong><small>${state.role==='brokerage'?'Brokerage preview':'Agent preview'} · Bay Area Realty · Demo only</small><small>Profile preferences are stored in this browser, not in a customer account.</small></div></div>`+
 `<div class="panel-grid equal"><section class="panel"><div class="eyebrow">PERSONAL DETAILS</div><h2>Profile settings</h2><p class="muted-copy">Use a sample display name. Do not enter real personal or client information into this public demo.</p><form id="profileSettingsForm"><div class="profile-form-grid"><label class="form-field">Display name<input name="name" value="${escapeHtml(current)}" minlength="1" maxlength="45" autocomplete="off" required></label><label class="form-field">Your title<select name="title">${['Managing broker','Real estate agent','Team lead','Brokerage owner'].map(x=>`<option value="${x}" ${p.title===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-field">Focus market<select name="market">${['Peninsula','San Francisco','East Bay','South Bay','North Bay','Entire Bay Area'].map(x=>`<option value="${x}" ${p.market===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-field">Default dashboard page<select name="start">${[['overview','Overview'],['opportunities','Opportunities'],['buyers','Buyer matches'],['crm','CRM intelligence'],['advisor','AI advisor'],['analytics','Analytics']].map(([key,name])=>`<option value="${key}" ${p.start===key?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="form-actions profile-form-actions">${btn('Save preferences','type="submit"','primary')}${btn('Restore profile defaults','data-reset-profile','ghost')}</div></form></section><section class="panel soft"><div class="eyebrow">NOTIFICATIONS</div><h2>Choose your briefing.</h2><p class="muted-copy">Preview preferences only. No emails, push alerts or notifications are sent.</p><form id="profileNotificationsForm"><label class="profile-preferences"><span><strong>Weekly intelligence briefing</strong><small>Save your preference for a future summary of opportunities and results.</small></span><input type="checkbox" name="briefing" ${p.briefing?'checked':''} aria-label="Weekly intelligence briefing"></label><label class="profile-preferences"><span><strong>Opportunity alerts</strong><small>Save your preference for new buyer-property matches and priority changes.</small></span><input type="checkbox" name="alerts" ${p.alerts?'checked':''} aria-label="Opportunity alerts"></label><div class="form-actions">${btn('Save notification preferences','type="submit"','primary')}</div></form><p class="subtle-note">Connecting Gmail or Calendar will always require a separate explicit authorization.</p></section></div>`+
 `<section class="panel section-gap"><div class="eyebrow">ACCOUNT & WORKSPACE</div><h2>Everything in one place.</h2><div class="profile-links-grid"><a class="profile-destination" href="account.html"><span>♙</span><strong>Account & security</strong><small>Sign-in methods and two-factor authentication. Requires a configured login.</small><em>↗</em></a><button type="button" class="profile-destination" data-nav="integrations"><span>⌁</span><strong>Connected services</strong><small>Review the CRM, property data and AI connection roadmap.</small><em>↗</em></button><button type="button" class="profile-destination" data-nav="activity"><span>◷</span><strong>Activity log</strong><small>See actions recorded in this browser.</small><em>↗</em></button></div></section>`;}
function renderIntegrations(){const cards=[['◎','CRM connection','Follow Up Boss, Lofty and other authorized CRMs','Requires customer OAuth/API permission, field mapping, sync policy and approval before external writes.'],['⌂','Property / parcel data','Commercial data or permitted county sources','Requires valid access, display and redistribution rights, record dates and provenance.'],['✦','Live AI advisor','Server-side model endpoint','Requires a protected API key, scoped retrieval, evaluation, guardrails and usage limits.'],['▤','Accounts & billing','Authentication, tenant isolation and payments','Requires hosted backend, access controls, audited payment flow and testing.']];return header('DATA & INTEGRATIONS','Connected only with permission.','The user experience is demonstrated here; live integrations must be configured in a secure backend.',btn('Download sample CRM CSV ↓','data-download="crm"'))+
 `<div class="panel-grid equal"><section class="panel"><div class="eyebrow">CONNECTOR ROADMAP</div><h2>Ready to configure, not secretly connected.</h2>${cards.map(([icon,title,desc,detail])=>`<div class="setting-card"><span class="setting-icon">${icon}</span><div class="row-main"><strong>${escapeHtml(title)}</strong><small>${escapeHtml(desc)}</small><small>${escapeHtml(detail)}</small></div><span class="pill amber">Not connected</span></div>`).join('')}</section><section class="panel soft"><div class="eyebrow">DATA SAFETY</div><h2>Private by design, not by a label.</h2><p class="muted-copy">Production requires authenticated accounts, tenant-scoped database queries, agent-level permissions, encryption, deletion controls and audit records. This standalone preview provides none of those production guarantees.</p><div class="callout warning"><strong>Do not enter real client data in this demo.</strong> Changes are saved in your browser’s local storage; anyone using the same browser profile may be able to view them.</div><h3>Approval workflow illustrated</h3><div class="report-line"><span>AI generates a proposed action</span><strong>Preview</strong></div><div class="report-line"><span>Agent reviews and approves</span><strong>Explicit click</strong></div><div class="report-line"><span>External CRM write</span><strong>Disabled</strong></div><div class="report-line"><span>Local audit event</span><strong>Enabled</strong></div></section></div>`;}
function renderActivity(){return header('AUDIT & ACTIVITY','Make every action understandable.','The preview records local interactions so agents can see what changed. Production logs must be tenant-scoped and tamper-resistant.',btn('Export CSV ↓','data-download="log"')+btn('Clear demo log','data-clear-log','ghost'))+
 `<div class="panel"><div class="eyebrow">LATEST DEMO EVENTS</div><h2>Recorded in this browser</h2>${state.activity.length?state.activity.map(a=>`<div class="ticket"><span class="ticket-icon">◷</span><div class="row-main"><strong>${escapeHtml(a.summary)}</strong><small>${escapeHtml(a.at)}</small></div><span class="pill dim">${escapeHtml(a.kind)}</span></div>`).join(''):'<div class="empty">No demo actions recorded yet. Open a property report, save a recommendation or complete a priority.</div>'}<p class="subtle-note">This is not a production audit system and does not establish regulatory compliance.</p></div>`;}
function advisorAnswer(q){
 const input=q.toLowerCase(),p=pendingContacts(),prefs=advisorPrefs();
 const context=`Your saved focus is ${prefs.focus.toLowerCase()} and your goal is ${prefs.goal}. `;
 if(/unrelated|weather|recipe|movie|game|sports/.test(input))return 'I focus on your real estate business. I can help with clients, property opportunities, brokerage performance, and next steps.';
 if(/land|zoning|parcel|build|utility/.test(input))return context+'For the fictional land examples, verify parcel identity, zoning, legal access, easements, utilities, and hazards with the responsible authorities. No parcel has been verified as buildable.';
 if(/buyer|match|client|propert|home/.test(input))return context+`${properties.filter(x=>matchingBuyers(x).length).length} fictional property recommendations match at least one sample buyer. Review the Buyer matches tab, confirm buyer requirements, and verify each property’s listing status and source information before outreach.`;
 if(/follow|contact|crm|lead|priority|today|focus|next/.test(input))return context+`${p.length} fictional contacts need review and ${openTasks().length} daily priorities remain. Start with ${p.slice(0,2).map(b=>b.name).join(' and ')||'your current queue'}, then review new buyer matches. Messages must be reviewed before sending.`;
 if(/team|broker|agent|performance/.test(input))return state.role==='brokerage'?context+`The fictional brokerage has ${team.length+state.teamAdded.length} demo seats and shows 18 appointments from 64 sample leads this month. Compare follow-up consistency and lead-source performance before adjusting the team's workflow.`:'This Agent preview shows only individual workflows. Brokerage-wide analysis requires an authorized brokerage workspace.';
 if(/goal|impact|roi|result|convert|pipeline|analytics|sale|business|strategy|grow/.test(input))return context+`The fictional monthly dataset shows 64 leads, 18 appointments and 4 closings. Compare conversion by stage, investigate overdue follow-ups, and track what happens after recommended actions. These figures are examples, not verified business results.`;
 if(/memory|remember|preference|personal/.test(input))return `Your demo goal is “${prefs.goal}.” Your focus is “${prefs.focus}.” These are saved in this browser and can be edited or cleared using Advisor preferences.`;
 if(/data|source|real|connect|privacy/.test(input))return 'This is a local simulation using fictional records. No live CRM, property feeds or model API are connected. The production advisor will use authorized, permission-scoped information with source dates and explicit approval for actions.';
 return context+'I can review sample CRM follow-ups, buyer-property matches, land due diligence, business analytics, and next steps. Try asking what needs attention today.';
}
function renderAdvisor(){const prefs=advisorPrefs();return header('DEDICATED REAL ESTATE ADVISOR','Your business, in focus.','Specialized in real estate workflows and business intelligence. This preview uses fictional sample data.',btn('Edit advisor preferences ↗','data-advisor-settings'))+
 `<div class="advisor-layout"><section class="panel chat-panel"><div class="panel-title"><div><div class="eyebrow">ESTATEIQ ADVISOR · ${LIVE_ADVISOR_URL ? 'LIVE MODEL' : 'DEMO'}</div><h2>Business advisor</h2></div><span class="pill">Real estate only</span></div><div class="callout"><strong>Current goal:</strong> ${escapeHtml(prefs.goal)}<br><strong>Focus:</strong> ${escapeHtml(prefs.focus)}</div><div class="chat-scroll" id="chatScroll" aria-live="polite"><div class="chat-bubble ai"><small>EstateIQ · ${LIVE_ADVISOR_URL ? 'Live AI' : 'Demo advisor'}</small>Good to see you, ${escapeHtml(profile().name)}. I can review sample client relationships, buyer matches and business performance. What would you like to examine?</div>${state.chat.map(c=>`<div class="chat-bubble ${c.role==='user'?'user':'ai'}">${c.role==='ai'?'<small>EstateIQ advisor</small>':''}${escapeHtml(c.text)}</div>`).join('')}</div><div class="prompt-row">${['What should I prioritize today?','Analyze my business performance','Find matching properties for buyers','Review land due diligence'].map(q=>`<button type="button" class="chip-button" data-prompt="${escapeHtml(q)}">${escapeHtml(q)}</button>`).join('')}</div><form class="ask-form" id="advisorForm"><label class="hidden" for="advisorQuestion">Ask EstateIQ</label><input id="advisorQuestion" name="question" maxlength="400" placeholder="Ask about your real estate business…" required>${btn('Ask →','type="submit"','primary')}</form><div class="advisor-utility">${btn('Edit preferences','data-advisor-settings','ghost')}${btn('Clear conversation','data-clear-advisor','ghost')}${btn('Clear advisor memory','data-clear-advisor-memory','ghost')}</div><p class="subtle-note">${LIVE_ADVISOR_URL ? 'Live AI is connected for fictional-data testing. Questions and preferences are sent to our OpenAI-powered development endpoint; do not enter real client data.' : 'Local scripted simulation. Deploy the OpenAI-powered Worker to enable real AI.'} No messages are sent or CRM records changed.</p></section><section class="panel soft"><div class="eyebrow">PERSONALIZED BUSINESS CONTEXT</div><h2>Advice grounded in your goals.</h2><div class="ticket"><span class="ticket-icon">01</span><div class="row-main"><strong>Business preferences</strong><small>${escapeHtml(prefs.goal)} · ${escapeHtml(prefs.focus)}</small></div></div><div class="ticket"><span class="ticket-icon">02</span><div class="row-main"><strong>Authorized customer information</strong><small>Future connection: tenant-scoped CRM, analytics, property records, and source dates.</small></div></div><div class="ticket"><span class="ticket-icon">03</span><div class="row-main"><strong>Specific recommendations</strong><small>Explain findings, distinguish estimates, and propose clear next steps.</small></div></div><div class="ticket"><span class="ticket-icon">04</span><div class="row-main"><strong>Approval before action</strong><small>Never send communications or change connected records without confirmation.</small></div></div><div class="callout warning">${LIVE_ADVISOR_URL ? 'Live model enabled for sample-data testing. Real CRM retrieval, account isolation and server-side memory are not connected.' : 'Live AI, business memory synchronization, and external integrations are not connected in this preview.'}</div>${btn('Manage personalization ↗','data-advisor-settings','primary')}</section></div>`;}
function advisorSettingsModal(){const prefs=advisorPrefs();modal('AI PERSONALIZATION','Advisor preferences',`<p>Set the goals that guide your initial EstateIQ experience. This demo saves preferences only in your browser.</p><form id="advisorSettingsForm"><label class="form-field">Primary business goal<textarea name="goal" rows="3" maxlength="240" required>${escapeHtml(prefs.goal)}</textarea></label><div class="form-grid"><label class="form-field">Business focus<select name="focus">${['Balanced business growth','Buyer matching','Client retention','Seller opportunities','Property and land research','Brokerage performance','Lead conversion'].map(x=>`<option ${prefs.focus===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-field">Advice style<select name="style">${['Concise recommendations','Detailed analysis','Action-oriented briefing'].map(x=>`<option ${prefs.style===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="form-actions">${btn('Save personalization','type="submit"','primary')}${btn('Reset to defaults','data-reset-advisor','ghost')}</div></form><p class="subtle-note">Settings may inform future demo responses. Production will require secure, permission-scoped storage and opt-in controls.</p>`,btn('Close','data-modal-close','secondary'));}
const renderers={profile:renderProfile,overview:renderOverview,opportunities:renderOpportunities,buyers:renderBuyers,crm:renderCrm,advisor:renderAdvisor,analytics:renderAnalytics,goals:renderGoals,team:renderTeam,reports:renderReports,integrations:renderIntegrations,activity:renderActivity};
let activePage='overview';
function render(){const renderPage=renderers[activePage]||renderOverview;$('#pageContent').innerHTML=renderPage();$('#pageCrumb').textContent=pageNames[activePage]||'Overview';$('#navOppCount').textContent=properties.length-state.dismissed.length;$('#workspacePlan').textContent=state.role==='brokerage'?'Brokerage demo':'Agent demo';$('#roleMode').value=state.role;updateProfileChrome();document.querySelectorAll('[data-page-link]').forEach(b=>{let selected=b.dataset.pageLink===activePage;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const sc=$('#chatScroll');if(sc)sc.scrollTop=sc.scrollHeight;}
