function modal(kicker,title,content,footer=''){ $('#modalKicker').textContent=kicker;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=content;$('#modalFooter').innerHTML=footer||btn('Close','data-modal-close','ghost');$('#modalLayer').hidden=false;document.body.style.overflow='hidden';$('#modalClose').focus();}
