function factBoxes(facts){return `<div class="info-grid">${facts.map(([k,v])=>`<div class="info-box"><span>${escapeHtml(k)}</span><strong>${escapeHtml(v)}</strong></div>`).join('')}</div>`;}
function openProperty(id){const p=getProperty(id);if(!p)return;if(!state.propertiesViewed.includes(id)){state.propertiesViewed.push(id);log('research',`Opened fictional report: ${p.title}`);}const matches=matchingBuyers(p);modal('PROPERTY INTELLIGENCE · FICTIONAL',p.title,
 `<p class="muted-copy">${escapeHtml(p.note)} <strong>Not a verified listing or property record.</strong></p>${factBoxes(p.facts)}<h3>Why EstateIQ recommended this</h3><p>${matches.length?`Matches ${escapeHtml(matches.map(b=>b.name).join(', '))} based on sample area, property type, bedroom and budget criteria.`:'Recommended for further market research; no sample buyer matches all current filters.'}</p><h3>Source and verification checklist</h3><ul>${p.sources.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ul><div class="callout warning">${escapeHtml(p.caution)}</div><p class="subtle-note">No actual parcel address, APN, owner, sale history or source feed is present in this preview.</p>`,btn(state.saved.includes(id)?'Remove from saved':'Save opportunity',`data-modal-save="${id}"`,'secondary')+ (matches.length?btn('Prepare buyer follow-up',`data-draft="${matches[0].id}"`,'primary'):'')+btn('Close','data-modal-close','ghost'));
 render();}
function openContact(id){const b=getBuyer(id);if(!b)return;const mp=matchedProperties(b);modal('CRM INTELLIGENCE · FICTIONAL',b.name,`<p class="muted-copy">${escapeHtml(b.note)}</p>${factBoxes([['Relationship',b.stage],['Target market',b.focus],['Budget',money(b.budget)],['Sample last contact',`${b.days} days ago`],['Assigned agent',b.owner],['Lead source',b.source]])}<h3>Relevant recommendations</h3>${mp.length?mp.map(p=>`<div class="row-line"><div class="row-main"><strong>${escapeHtml(p.title)}</strong><small>${escapeHtml(p.status)}</small></div>${btn('Review',`data-property="${p.id}"`,'ghost')}</div>`).join(''):'<p>No matching candidates in the sample set.</p>'}<div class="callout warning">Private customer data is not connected. Reviewing a contact here cannot update a real CRM.</div>`,btn(state.reviewed.includes(id)?'Marked reviewed':'Mark reviewed',`data-reviewed="${id}"`,'secondary')+btn('Prepare follow-up',`data-draft="${id}"`,'primary')+btn('Close','data-modal-close','ghost'));}
let currentDraft='';
function openDraft(id){const b=getBuyer(id);if(!b)return;const matches=matchedProperties(b);const related=matches[0];currentDraft=`Subject: Checking in about your ${b.focus} search\n\nHi ${b.name.split(' ')[0]},\n\nI wanted to check in on your current plans and preferences. ${related?`I found a research candidate in ${related.location} that may align with what you described. I’ll verify the details and availability before sharing a full report.`:'I can review new possibilities based on your updated criteria.'}\n\nWould you like to reconnect this week?\n\nBest,\nYour real estate agent`;
 log('draft',`Prepared fictional follow-up draft for ${b.name}`);
 modal('PREPARED FOLLOW-UP · APPROVAL REQUIRED',`Draft for ${b.name}`,`<p class="muted-copy">Review and edit this sample copy before deciding to use it. Nothing will be sent automatically.</p><label class="form-field">Proposed message<textarea id="draftText" rows="11" maxlength="3000">${escapeHtml(currentDraft)}</textarea></label><div class="callout warning">Copying text does not send an email. “Approve demo task” only records an action in this browser; it does not write to any CRM.</div>`,btn('Copy draft','data-copy-draft','secondary')+btn('Approve demo task',`data-approve-draft="${id}"`,'primary')+btn('Cancel','data-modal-close','ghost'));}
function approveDraft(id){const b=getBuyer(id);if(!b)return;state.actions.push({id:b.id,name:b.name,body:$('#draftText')?.value||currentDraft,at:new Date().toLocaleString()});log('approval',`Approved local demo follow-up task for ${b.name}; not sent or synced`);closeModal();render();showToast('Approved in demo log only. No message was sent.');}
function markReviewed(id){const b=getBuyer(id);if(!b)return;if(!state.reviewed.includes(id)){state.reviewed.push(id);log('review',`Marked fictional contact ${b.name} reviewed`);}closeModal();render();showToast('Contact reviewed in demo only.');}
function csvCell(x){return '"'+String(x??'').replace(/"/g,'""')+'"';}
function downloadFile(filename,content,type){const blob=new Blob([content],{type});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);showToast('Download prepared.');}
function download(kind){if(kind==='crm'){downloadFile('EstateIQ_FICTIONAL_CRM_template.csv',[['contact_name','type','market','budget','assigned_agent','last_contact_days','lead_source'],...buyers.map(b=>[b.name,b.stage,b.focus,b.budget,b.owner,b.days,b.source])].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');return;}
 if(kind==='log'){downloadFile('EstateIQ_demo_activity.csv',[['date','type','activity'],...state.activity.map(a=>[a.at,a.kind,a.summary])].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');return;}
 if(kind==='impact'){const rows=[['metric','sample_count','measurement_note'],['Recommendations delivered',properties.length,'Fictional seeded candidates'],['Reports opened',state.propertiesViewed.length,'Unique local report opens'],['Saved recommendations',state.saved.length,'Local bookmarks'],['Priorities completed',state.tasksDone.length,'Local user actions'],['Follow-up drafts approved',state.actions.length,'No messages sent or CRM writes'],['Verified transactions','','Not connected; cannot attribute sales']];downloadFile('EstateIQ_demo_impact.csv',rows.map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');return;}
 const txt=["ESTATEIQ — SAMPLE BUSINESS BRIEFING","FICTIONAL DEMO — NOT LIVE DATA",`Generated: ${new Date().toLocaleString()}`,'',`Recommendations: ${properties.length-state.dismissed.length}`,`Buyer-to-property matches: ${properties.reduce((n,p)=>n+matchingBuyers(p).length,0)}`,`Follow-ups awaiting review: ${pendingContacts().length}`,`Priorities completed: ${state.tasksDone.length} / ${baseTasks.length}`,`Reports opened: ${state.propertiesViewed.length}`,`Local approved tasks: ${state.actions.length}`,'','Next steps: review current client needs, verify authorized property records, check zoning/access for land, and record actual customer outcomes.','','Methodology: This report contains fictional seeded metrics and browser-local interactions. No outcomes are attributed to EstateIQ.'];downloadFile('EstateIQ_sample_weekly_briefing.txt',txt.join('\n'),'text/plain;charset=utf-8');}
function addAgentModal(){if(state.role!=='brokerage')return;modal('BROKERAGE SEATS · DEMO','Add a fictional agent',`<p class="muted-copy">This simulates agent-seat management. Do not enter a real person’s private details; no invitation will be sent.</p><form id="addAgentForm"><label class="form-field">Demo display name<input name="name" required maxlength="45" placeholder="e.g. Demo Agent" autocomplete="off"></label><div class="form-actions">${btn('Add sample seat','type="submit"','primary')}</div></form><p class="subtle-note">The 10-seat allowance shown in this preview is a draft commercial structure, not a live billing plan.</p>`,btn('Close','data-modal-close','ghost'));}
function handleAddAgent(form){const input=new FormData(form).get('name').toString().trim();if(!input)return;const id='demo-'+Date.now();state.teamAdded.push({id,name:input,initials:input.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),role:'Agent',leads:0,appointments:0,closings:0});log('seat',`Added fictional agent seat: ${input}`);closeModal();render();showToast('Sample seat added locally; no invitation sent.');}
const LIVE_ADVISOR_URL = String(window.ESTATEIQ_LIVE_AI?.endpoint || '').trim();
let advisorPending=false;
async function askAdvisor(q){
 const clean=String(q||'').trim().slice(0,400);if(!clean || advisorPending)return;
 const history=state.chat.slice(-8).map(c=>({role:c.role==='ai'?'assistant':'user',content:c.text}));
 state.chat.push({role:'user',text:clean});state.chat=state.chat.slice(-28);
 if(!LIVE_ADVISOR_URL){state.chat.push({role:'ai',text:advisorAnswer(clean)});log('advisor','Asked scripted demo advisor a question');navigate('advisor');return;}
 advisorPending=true; state.chat.push({role:'ai',text:'Reviewing your question…'});navigate('advisor');
 try{
  const response=await fetch(LIVE_ADVISOR_URL,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question:clean,history,preferences:advisorPrefs()})});
  const data=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(data.error||'The advisor is temporarily unavailable.');
  if(typeof data.answer!=='string'||!data.answer.trim())throw new Error('No response was returned.');
  state.chat[state.chat.length-1]={role:'ai',text:data.answer.slice(0,5000)};
  log('advisor','Received live model response to sample-data question');
 }catch(err){state.chat[state.chat.length-1]={role:'ai',text:'The live advisor could not respond. '+String(err.message||'Please try again.').slice(0,160)};}
 finally{advisorPending=false;save();navigate('advisor');}
}
document.addEventListener('click',e=>{
 if(!e.target.closest('#profileMenuWrap'))setProfileMenu(false);
 const t=e.target.closest('button');if(!t)return;
 if(t.id==='profileMenuToggle'){setProfileMenu($('#profileMenu').hidden);return;}
 if(t.id==='profileHelp'){helpModal();return;}
 if(t.hasAttribute('data-reset-profile')){if(confirm('Restore fictional profile preferences to the starting values?')){state.profile={...profileDefaults};log('profile','Reset local demo profile preferences');render();showToast('Demo profile preferences restored.');}return;}

 if(t.hasAttribute('data-page-link')){navigate(t.dataset.pageLink);return;}
 if(t.hasAttribute('data-nav')){navigate(t.dataset.nav);return;}
 if(t.hasAttribute('data-role')){state.role=t.dataset.role;save();navigate('team');return;}
 if(t.hasAttribute('data-task-open')){const a=baseTasks.find(x=>x.id===t.dataset.taskOpen);if(a?.property)openProperty(a.property);else if(a?.contact)openContact(a.contact);else navigate(a?.page||'overview');return;}
 if(t.hasAttribute('data-property')){openProperty(t.dataset.property);return;}
 if(t.hasAttribute('data-contact')){openContact(t.dataset.contact);return;}
 if(t.hasAttribute('data-draft')){openDraft(t.dataset.draft);return;}
 if(t.hasAttribute('data-save')||t.hasAttribute('data-modal-save')){const id=t.dataset.save||t.dataset.modalSave;const p=getProperty(id);if(!p)return;const saved=state.saved.includes(id);state.saved=saved?state.saved.filter(x=>x!==id):[...state.saved,id];log('recommendation',`${saved?'Removed saved':'Saved'} sample opportunity: ${p.title}`);if(!$('#modalLayer').hidden)openProperty(id);else render();showToast(saved?'Removed from saved opportunities.':'Saved in this browser.');return;}
 if(t.hasAttribute('data-dismiss')){const p=getProperty(t.dataset.dismiss);if(p&&!state.dismissed.includes(p.id)){state.dismissed.push(p.id);log('recommendation',`Dismissed fictional recommendation: ${p.title}`);render();showToast('Opportunity dismissed. You can restore it.');}return;}
 if(t.hasAttribute('data-reviewed')){markReviewed(t.dataset.reviewed);return;}
 if(t.hasAttribute('data-approve-draft')){approveDraft(t.dataset.approveDraft);return;}
 if(t.hasAttribute('data-copy-draft')){const copy=$('#draftText')?.value||'';if(navigator.clipboard?.writeText){navigator.clipboard.writeText(copy).then(()=>showToast('Draft copied; nothing sent.')).catch(()=>fallbackCopy(copy));}else fallbackCopy(copy);return;}
 if(t.hasAttribute('data-filter')){state.filter=t.dataset.filter;save();render();return;}
 if(t.hasAttribute('data-period')){state.period=t.dataset.period;save();render();return;}
 if(t.hasAttribute('data-clear-filters')){state.filter='all';state.search='';save();render();return;}
 if(t.hasAttribute('data-restore-dismissed')){state.dismissed=[];log('recommendation','Restored all dismissed sample recommendations');render();return;}
 if(t.hasAttribute('data-prompt')){askAdvisor(t.dataset.prompt);return;}
 if(t.hasAttribute('data-advisor-settings')){advisorSettingsModal();return;}
 if(t.hasAttribute('data-clear-advisor')){if(confirm('Clear demo advisor conversation in this browser?')){state.chat=[];log('advisor','Cleared demo conversation');render();showToast('Conversation cleared.');}return;}
 if(t.hasAttribute('data-clear-advisor-memory')){if(confirm('Clear saved advisor personalization and conversation?')){state.advisorPreferences={...advisorDefaults};state.chat=[];log('advisor','Cleared demo advisor preferences and conversation');render();showToast('Advisor memory cleared.');}return;}
 if(t.hasAttribute('data-reset-advisor')){state.advisorPreferences={...advisorDefaults};log('advisor','Restored demo advisor defaults');advisorSettingsModal();showToast('Advisor preferences restored.');return;}
 if(t.hasAttribute('data-download')){download(t.dataset.download);return;}
 if(t.hasAttribute('data-print')){window.print();return;}
 if(t.hasAttribute('data-add-agent')){addAgentModal();return;}
 if(t.hasAttribute('data-clear-log')){if(confirm('Clear local demo activity log?')){state.activity=[];save();render();}return;}
 if(t.hasAttribute('data-modal-close')||t.id==='modalClose'){closeModal();return;}
});
function fallbackCopy(txt){const el=$('#draftText');if(el){el.focus();el.select();try{document.execCommand('copy');showToast('Draft selected/copied. No message sent.');}catch{showToast('Select the text and copy it manually.');}}}
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-task]')){completeTask(t.dataset.task);return;}});
document.addEventListener('input',e=>{if(e.target.id==='oppSearch'){state.search=e.target.value;save();const cursor=e.target.selectionStart;render();const field=$('#oppSearch');field?.focus();try{field?.setSelectionRange(cursor,cursor);}catch{}}});
document.addEventListener('submit',e=>{const form=e.target;if(form.id==='advisorForm'){e.preventDefault();askAdvisor(new FormData(form).get('question')?.toString()||'');return;}if(form.id==='advisorSettingsForm'){e.preventDefault();const fd=new FormData(form);const goal=String(fd.get('goal')||'').trim().slice(0,240),focus=String(fd.get('focus')||''),style=String(fd.get('style')||'');if(!goal){showToast('Please enter a business goal.');return;}state.advisorPreferences={goal,focus,style};log('advisor','Updated demo advisor personalization');closeModal();render();showToast('Advisor preferences saved.');return;}if(form.id==='goalsForm'){e.preventDefault();let fd=new FormData(form),a=Number(fd.get('appointments')),c=Number(fd.get('closings'));if(!Number.isInteger(a)||!Number.isInteger(c)||a<1||c<1||a>10000||c>10000){showToast('Enter goals between 1 and 10,000.');return;}state.goals={appointments:a,closings:c};log('goal',`Updated fictional appointment goal to ${a}, closing goal to ${c}`);render();showToast('Demo goals saved in this browser.');return;}if(form.id==='profileSettingsForm'){e.preventDefault();const fd=new FormData(form);const name=String(fd.get('name')||'').trim().slice(0,45);const titles=['Managing broker','Real estate agent','Team lead','Brokerage owner'],markets=['Peninsula','San Francisco','East Bay','South Bay','North Bay','Entire Bay Area'],starts=['overview','opportunities','buyers','crm','advisor','analytics'];if(!name){showToast('Enter a display name.');return;}state.profile={...profile(),name,title:titles.includes(fd.get('title'))?fd.get('title'):profileDefaults.title,market:markets.includes(fd.get('market'))?fd.get('market'):profileDefaults.market,start:starts.includes(fd.get('start'))?fd.get('start'):profileDefaults.start};log('profile','Updated local demo profile and workspace preferences');render();showToast('Demo profile preferences saved in this browser.');return;}if(form.id==='profileNotificationsForm'){e.preventDefault();const fd=new FormData(form);state.profile={...profile(),briefing:fd.has('briefing'),alerts:fd.has('alerts')};log('profile','Updated demo notification preferences; no notifications sent');render();showToast('Preferences saved. No notifications will be sent.');return;}if(form.id==='addAgentForm'){e.preventDefault();handleAddAgent(form);return;}});
$('#roleMode').addEventListener('change',e=>{state.role=e.target.value;log('workspace',`Switched to ${state.role} demo preview`);navigate(activePage);});
$('#sidebarToggle').addEventListener('click',()=>{const s=$('#sidebar');s.classList.toggle('open');const opened=s.classList.contains('open');$('#sidebarBackdrop').hidden=!opened;$('#sidebarToggle').setAttribute('aria-expanded',String(opened));});
$('#sidebarBackdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebarBackdrop').hidden=true;$('#sidebarToggle').setAttribute('aria-expanded','false');});
$('#resetDemo').addEventListener('click',()=>{if(confirm('Reset all saved recommendations, demo goals, tasks, drafts and activity in this browser?')){state=JSON.parse(JSON.stringify(seed));save();navigate('overview');showToast('Demo reset to fictional starting state.');}});
$('#modalLayer').addEventListener('click',e=>{if(e.target.id==='modalLayer')closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#profileMenu').hidden){setProfileMenu(false);$('#profileMenuToggle').focus();}closeModal();$('#sidebar').classList.remove('open');$('#sidebarBackdrop').hidden=true;$('#sidebarToggle').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1),false));
navigate(location.hash.slice(1)||profile().start||'overview',false);
